func (s *GitStore) getSessionsBranchTree() (*object.Tree, error) {
	ref, err := s.repo.Reference(s.refs.Read, true)
	if err != nil {
		if !s.refs.PrimaryFetchableFromOrigin() {
			return nil, fmt.Errorf("sessions ref %s not found: %w", s.refs.Read, err)
