func (s *GitStore) getSessionsBranchTree() (*object.Tree, error) {
	ref, err := s.repo.Reference(s.refs.Read, true)
	if err != nil {
		// Fallback to origin only when reads target the same ref we push: a
		// fresh clone may not have the local primary yet, but if origin tracks
		// it we can read from refs/remotes/origin. In v1.1 canary mode Read
		// is the local-only mirror, not Primary, so the fallback must skip.
		if s.refs.Read != s.refs.Primary || !s.refs.PrimaryFetchableFromOrigin() {
			return nil, fmt.Errorf("sessions ref %s not found: %w", s.refs.Read, err)
		}
		remoteRefName := plumbing.NewRemoteReferenceName("origin", s.refs.Primary.Short())
		ref, err = s.repo.Reference(remoteRefName, true)
		if err != nil {
			return nil, fmt.Errorf("sessions branch not found: %w", err)
		}
	}
	// ... rest unchanged
}
```

Semantic notes:
- The fallback fires only when `Read == Primary` AND Primary is in `Push`. Today's v1-only mode hits both; today's v1.1-canary mode reads the local-only mirror so the first conjunct is false and the fallback is skipped — matching the original `s.committedReadRef != defaultCommittedReadRef()` gate.
- The fallback uses `refs.Primary.Short()` for the remote-tracking branch name. Today Primary is the v1 branch, so this is `entire/checkpoints/v1`.
